from pathlib import Path
import json,hashlib,shutil
from PIL import Image
ROOT=Path(__file__).resolve().parent.parent
ASSETS=ROOT.parents[1]
def build():
 data=json.loads((ROOT/'records/production_plan.json').read_text());reviews=json.loads((ROOT/'records/reviews.json').read_text()) if (ROOT/'records/reviews.json').exists() else{};items=[]
 for a in data['assets']:
  review=reviews.get(a['id'],{});v=review.get('version','v01');stem=f"{a['id']}_{v}";p=ROOT/'candidates'/f'{stem}.png';item={**a,'version':v,'status':'pending','candidate':f'candidates/{stem}.png','source':f'originals/{stem}_raw.png','generation_record':f'records/generation_{stem}.json','output':f"sprites/{a['folder']}/{a['id']}.png",'checks':review,'preview':f'previews/{stem}_review.png','gif':f'previews/{stem}.gif' if a['frames']>1 else None,'fps':8 if a['frames']>1 else None,'game_fps':16 if a.get('action')=='attack' else 8 if a['frames']>1 else None,'pivot':[a['w']//2,a['h']-2] if a['anchor'] in ('bottom','float') else[a['w']//2,a['h']//2]}
  if p.exists():
   item['status']=review.get('status','candidate');item['technical']=json.loads((ROOT/'records'/f'check_{stem}.json').read_text())
  gp=ROOT/item['generation_record']
  if gp.exists():item['provenance']=json.loads(gp.read_text())
  if review.get('status')=='accepted':
   dest=ASSETS/item['output'];dest.parent.mkdir(parents=True,exist_ok=True)
   if dest.exists() and dest.read_bytes()!=p.read_bytes():
    backup=ROOT/'backups'/f"{a['id']}_before_task{data['task']}.png"
    if not backup.exists():shutil.copy2(dest,backup)
   shutil.copy2(p,dest);shutil.copy2(p,ROOT/'approved'/f"{a['id']}.png");item['approved']=f"approved/{a['id']}.png";item['sha256']=hashlib.sha256(p.read_bytes()).hexdigest()
  items.append(item)
 manifest={'task':data['task'],'date':data['date'],'accepted':sum(a['status']=='accepted' for a in items),'total':len(items),'status':'art_self_check_complete' if all(a['status']=='accepted' for a in items) else'in_progress','game_tested':False,'tiling_4x4':'N/A - no ground tiles in this task','assets':items};(ROOT/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
 rows=json.dumps(items,ensure_ascii=False).replace('</','<\\/')
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>Task TASK Helheim art review</title><style>body{background:#121721;color:#e5eaf0;margin:24px;font:15px system-ui}h1{font-size:24px}h2{font-size:18px}header{position:sticky;top:0;background:#121721ee;padding:12px 0;z-index:2}button{background:#2a3748;color:white;border:1px solid #65758b;padding:6px 12px;cursor:pointer}section{border-top:1px solid #3a4657;padding:18px 0;margin-top:16px}figure{display:inline-block;vertical-align:top;margin:12px 24px 8px 0}canvas{image-rendering:pixelated;outline:1px solid #364050}figcaption{font-size:12px;margin:8px 0}.preview{overflow:auto}.controls{margin:10px 0;display:flex;gap:8px;align-items:center;flex-wrap:wrap}a{color:#c1d8f1}.status{color:#ecc77e}.accepted{color:#9ee6b9}pre{white-space:pre-wrap;font-size:12px}p{line-height:1.7;max-width:1150px}</style><header><h1>任务TASK · 第2关美术验收</h1><button id="pause">全部暂停</button> <button id="step">全部下一帧</button> <a href="manifest.json">manifest.json</a> · <a href="README.md">README.md</a></header><p>左侧1倍为实际像素大小，右侧4倍为最近邻放大；#121721背景。动画预览8fps，攻击游戏建议16fps。非循环动作自动重播仅供检查。无地块，4×4平铺不适用；本页状态为美术自检，未由本代理游戏实测。</p><main></main><script>
 const assets=ITEMS,main=document.querySelector('main'),states=[];let play=true;const only=new URLSearchParams(location.search).get('only');
 for(const a of assets){if(only&&!only.split(',').includes(a.id))continue;const s=document.createElement('section');s.id=a.id;s.innerHTML=`<h2>${a.label} <code>${a.id}</code></h2><div class="status ${a.status==='accepted'?'accepted':''}">${a.status} · ${a.w}×${a.h} × ${a.frames} · ${a.technical?.colors??'?'}色 · ${a.loop?'循环':'单次/静态'}</div>`;main.append(s);if(!a.technical){s.insertAdjacentHTML('beforeend','<p>尚无候选。</p>');continue}const row=document.createElement('div');row.className='preview';s.append(row);const canvases=[];
 for(const k of [1,4]){const f=document.createElement('figure'),c=document.createElement('canvas'),cap=document.createElement('figcaption');c.width=a.w*k;c.height=a.h*k;cap.textContent=k+'× · #121721';f.append(c,cap);row.append(f);canvases.push(c)}
 const controls=document.createElement('div');controls.className='controls';s.append(controls);const toggle=document.createElement('button'),next=document.createElement('button'),label=document.createElement('span');toggle.textContent='暂停';next.textContent='下一帧';controls.append(toggle,next,label);const links=document.createElement('span');links.innerHTML=`<a href="${a.candidate}">PNG</a> · <a href="${a.source}">原图</a> · <a href="${a.generation_record}">Prompt/来源</a>`+(a.gif?` · <a href="${a.gif}">8fps 4×GIF</a>`:'');controls.append(links);const im=new Image();const state={a,frame:0,play:true,draw:()=>{if(!im.complete||!im.naturalWidth)return;for(const c of canvases){const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.fillStyle='#121721';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(im,state.frame*a.w,0,a.w,a.h,0,0,c.width,c.height)}label.textContent=`帧 ${state.frame+1}/${a.frames}`}};im.onload=state.draw;im.src=a.candidate;states.push(state);toggle.onclick=()=>{state.play=!state.play;toggle.textContent=state.play?'暂停':'播放'};next.onclick=()=>{state.play=false;toggle.textContent='播放';state.frame=(state.frame+1)%a.frames;state.draw()};if(a.frames===1){toggle.disabled=true;next.disabled=true}const details=document.createElement('details');details.innerHTML='<summary>自检记录</summary>';const pre=document.createElement('pre');pre.textContent=JSON.stringify({checks:a.checks,technical:a.technical},null,2);details.append(pre);s.append(details)}
 document.getElementById('pause').onclick=()=>{play=!play;document.getElementById('pause').textContent=play?'全部暂停':'全部播放'};document.getElementById('step').onclick=()=>{play=false;document.getElementById('pause').textContent='全部播放';for(const s of states){s.frame=(s.frame+1)%s.a.frames;s.draw()}};setInterval(()=>{if(play)for(const s of states)if(s.play){s.frame=(s.frame+1)%s.a.frames;s.draw()}},125);
 </script></html>'''.replace('TASK',data['task']).replace('ITEMS',rows)
 (ROOT/'gallery.html').write_text(page);print(json.dumps({'task':data['task'],'accepted':manifest['accepted'],'total':manifest['total'],'candidates':sum('technical' in a for a in items)}))
if __name__=='__main__':build()
